// Example: linear search – O(n) worst case, Ω(1) best case, Θ(n) average case
int linearSearch(const vector<int>& arr, int key){
    for(size_t i=0;i<arr.size();++i){ // dominant operation: comparison
        if(arr[i]==key) return i; // may return on first check → Ω(1)
    }
    return -1; // scanned whole array → O(n)
}

