// Implementing a Stack ADT using a vector
class StackADT {
private:
    vector<int> data; // Hidden implementation detail

public:
    void push(int val) {
        data.push_back(val);
    }
    void pop() {
        if (!data.empty()) data.pop_back();
    }
    int peek() {
        return data.empty() ? -1 : data.back();
    }
    bool isEmpty() {
        return data.empty();
    }
};

