#include <bits/stdc++.h>
using namespace std;

// in‑place reversal of a sub‑array
template <typename T>
void reverseArr(T a[], int l, int r) {
    while (l < r) swap(a[l++], a[r--]); // important line: swap elements
}

// rotation by k to the right using three reversals
template <typename T>
void rotateRight(T a[], int n, int k) {
    if (n == 0) return;
    k = ((k % n) + n) % n;          // normalize (handles negative k)
    reverseArr(a, 0, n-1);          // 1️⃣ reverse whole array
    reverseArr(a, 0, k-1);          // 2️⃣ reverse first k elements
    reverseArr(a, k, n-1);          // 3️⃣ reverse rest
}

int main() {
    int arr[] = {1,2,3,4,5,6,7};
    int n = sizeof(arr)/sizeof(arr[0]);
    rotateRight(arr, n, 3); // rotate right by 3 → {5,6,7,1,2,3,4}
    for (int x: arr) cout << x << ' ';
    return 0;
}

