#include <iostream>
#include <vector>
using namespace std;

int findMajorityElement(vector<int>& nums) {
    int candidate = -1;
    int count = 0;

    // Step 1: Find the candidate
    for (int num : nums) {
        if (count == 0) {
            candidate = num;
        }
        count += (num == candidate) ? 1 : -1;
    }

    // Step 2: Verify the candidate (mandatory if majority isn't guaranteed)
    int frequency = 0;
    for (int num : nums) {
        if (num == candidate) frequency++;
    }

    if (frequency > nums.size() / 2) {
        return candidate;
    }
    return -1; // No majority element exists
}

int main() {
    vector<int> nums = {2, 2, 1, 1, 1, 2, 2};
    cout << "Majority Element: " << findMajorityElement(nums) << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

vector<int> buildLPS(const string &pat){
    int m = pat.size();
    vector<int> lps(m,0);
    int len = 0; // length of previous longest prefix suffix
    for(int i=1;i<m;){
        if(pat[i]==pat[len]){
            len++; lps[i]=len; i++;
        }else if(len!=0){
            len = lps[len-1]; // fall back
        }else{
            lps[i]=0; i++;
        }
    }
    return lps;
}

vector<int> KMPsearch(const string &txt, const string &pat){
    vector<int> matches;
    int n=txt.size(), m=pat.size();
    vector<int> lps = buildLPS(pat);
    int i=0,j=0;
    while(i<n){
        if(txt[i]==pat[j]){ i++; j++; }
        if(j==m){
            matches.push_back(i-j); // match at index i-j
            j = lps[j-1]; // allow overlapping matches
        }else if(i<n && txt[i]!=pat[j]){
            if(j!=0) j = lps[j-1];
            else i++;
        }
    }
    return matches;
}

int main(){
    string T = "ababcababcababc";
    string P = "ababc";
    auto res = KMPsearch(T,P);
    for(int idx:res) cout << "Match at index "<<idx<<"\n"; // important lines: buildLPS and fallback using lps
    return 0;
}

#include <iostream>
