void reverseDLL(Node*& head){
    Node* cur = head;
    Node* temp = nullptr;
    while(cur){
        // swap next and prev
        temp = cur->prev;
        cur->prev = cur->next;
        cur->next = temp;
        // move to next node (which is previous before swap)
        cur = cur->prev;
    }
    // after loop, temp points to old head's prev (new head)
    if(temp) head = temp->prev; // new head is last processed node
}

// Sketch: Use `unordered_map<int, Node*>` for fast key lookup.
// The DLL holds cache entries with most‑recent at front.
// On `get(key)`: if key in map, move its node to front and return value.
// On `put(key,value)`: if key exists, update value and move to front.
// If capacity exceeded, remove tail node (least recent) and erase its key from map.
// All operations are O(1).

void insertAfter(Node* prevNode, int val){
    if(!prevNode) return; // cannot insert after null
    Node* newNode = new Node(val);
    newNode->next = prevNode->next;
    newNode->prev = prevNode;
    if(prevNode->next) prevNode->next->prev = newNode;
    prevNode->next = newNode;
}

