    for (int i = 1; i < n; i++) p_pow[i] = (p_pow[i - 1] * p) % m;
    for (int i = 0; i < n; i++) pref[i + 1] = (pref[i] * p + (s[i] - 'a' + 1)) % m;
    cout << "Hash of sub(3,6): " << getSubstringHash(3, 6, pref, p_pow, m) << endl;
