#include <iostream>
#include <vector>
#include <string>
using namespace std;

vector<int> computeZ(string s) {
    int n = s.length();
    vector<int> z(n, 0);
    int L = 0, R = 0;
    for (int i = 1; i < n; i++) {
        if (i > R) {
            L = R = i;
            while (R < n && s[R - L] == s[R])
                R++;
            z[i] = R - L;
            R--;
        } else {
            int k = i - L;
            if (z[k] < R - i + 1) {
                z[i] = z[k];
            } else {
                L = i;
                while (R < n && s[R - L] == s[R])
                    R++;
                z[i] = R - L;
                R--;
            }
        }
    }
    return z;
}

void search(string text, string pattern) {
    string concat = pattern + "$" + text;
    vector<int> z = computeZ(concat);
    int pLen = pattern.length();
    for (int i = 0; i < concat.length(); i++) {
        if (z[i] == pLen) {
            cout << "Pattern found at index " << i - pLen - 1 << endl;
        }
    }
}

