#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
using namespace std;

string longestPalindrome(string s) {
    if (s.empty()) return "";
    string t = "^";
    for (char c : s) t += "#" + string(1, c);
    t += "#$";

    int n = t.length();
    vector<int> p(n, 0);
    int c = 0, r = 0;
    int maxLen = 0, centerIndex = 0;

    for (int i = 1; i < n - 1; i++) {
        int i_mirror = 2 * c - i;
        if (r > i)
            p[i] = min(r - i, p[i_mirror]);

        while (t[i + 1 + p[i]] == t[i - 1 - p[i]])
            p[i]++;

        if (i + p[i] > r) {
            c = i;
            r = i + p[i];
        }

        if (p[i] > maxLen) {
            maxLen = p[i];
            centerIndex = i;
        }
    }

    int start = (centerIndex - maxLen) / 2;
    return s.substr(start, maxLen);
}

int main() {
    string s = "babad";
    cout << "Longest Palindromic Substring: " << longestPalindrome(s) << endl;
    return 0;
}

