#include <iostream>

struct Node{int data; Node* next;};

class NodePool{
    Node* freeHead=nullptr; // head of free list
public:
    // acquire a node: pop from free list or allocate new
    Node* acquire(){
        if(freeHead){
            Node* n=freeHead;            
            freeHead=freeHead->next;    // pop
            n->next=nullptr;            // clean
            return n;
        }
        return new Node{0,nullptr}; // fresh node
    }
    // release a node: push onto free list
    void release(Node* n){
        n->next=freeHead; // push
        freeHead=n;
    }
};

int main(){
    NodePool pool;
    // acquire three nodes
    Node* a=pool.acquire(); a->data=10;
    Node* b=pool.acquire(); b->data=20;
    Node* c=pool.acquire(); c->data=30;
    // link them
    a->next=b; b->next=c;
    // print list
    for(Node* cur=a; cur; cur=cur->next) std::cout<<cur->data<<" ";
    std::cout<<"\n";
    // release nodes back to pool
    pool.release(c); pool.release(b); pool.release(a);
    // acquire again – should reuse first released node (c)
    Node* d=pool.acquire();
    std::cout<<"Reused node data (should be 0): "<<d->data<<"\n";
    return 0;
}

