struct Node {
    int coeff;
    int pow;
    Node* next;
    Node(int c, int p) : coeff(c), pow(p), next(nullptr) {}
};

void insertTerm(Node*& head, int c, int p) {
    Node* newNode = new Node(c, p);
    if (!head || head->pow < p) {
        newNode->next = head;
        head = newNode;
    } else {
        Node* curr = head;
        while (curr->next && curr->next->pow > p) {
            curr = curr->next;
        }
        if (curr->pow == p) {
            curr->coeff += c;
            delete newNode;
        } else {
            newNode->next = curr->next;
            curr->next = newNode;
        }
    }
}

void printPoly(Node* head) {
    while (head) {
        cout << head->coeff << "x^" << head->pow;
        if (head->next) cout << " + ";
        head = head->next;
    }
    cout << endl;
}

