#include <bits/stdc++.h>
using namespace std;

class Stack {
    int capacity;          // maximum size
    int top;               // index of current top
    vector<int> arr;       // underlying storage
public:
    Stack(int cap) : capacity(cap), top(-1), arr(cap) {}
    bool isEmpty() const { return top == -1; }
    bool isFull() const { return top == capacity-1; }
    void push(int x) {               // O(1)
        if (isFull()) { cerr << "Overflow!" << endl; return; }
        arr[++top] = x;               // increment then store
    }
    int pop() {                      // O(1)
        if (isEmpty()) { cerr << "Underflow!" << endl; return -1; }
        return arr[top--];           // return then decrement
    }
    int peek() const {               // O(1)
        if (isEmpty()) { cerr << "Empty stack" << endl; return -1; }
        return arr[top];
    }
};

int main(){
    Stack s(5);
    s.push(10); s.push(20); s.push(30);
    cout << "Top element: " << s.peek() << "\n"; // 30
    cout << "Popped: " << s.pop() << "\n";      // 30
    cout << "New top: " << s.peek() << "\n";   // 20
    return 0;
}

