    // Hash map: unordered_map<int, Node*>
    // Doubly Linked List node: {key, val, prev, next}
};

code.src:
#include <iostream>
#include <unordered_map>
using namespace std;

class LRUCache {
    struct Node {
        int key, val;
        Node* prev;
        Node* next;
        Node(int k, int v) : key(k), val(v), prev(nullptr), next(nullptr) {}
    };

    int capacity;
    unordered_map<int, Node*> mp;
    Node* head = new Node(-1, -1); // Dummy head
    Node* tail = new Node(-1, -1); // Dummy tail

    void addNode(Node* newnode) {
        Node* temp = head->next;
        head->next = newnode;
        newnode->prev = head;
        newnode->next = temp;
        temp->prev = newnode;
    }

    void deleteNode(Node* node) {
        Node* prevv = node->prev;
        Node* nextv = node->next;
        prevv->next = nextv;
        nextv->prev = prevv;
    }

public:
    LRUCache(int cap) {
        capacity = cap;
        head->next = tail;
        tail->prev = head;
    }

    int get(int key) {
        if (mp.find(key) == mp.end()) return -1;
        Node* resNode = mp[key];
        deleteNode(resNode);
        addNode(resNode); // Move to front (most recently used)
        mp[key] = head->next;
        return resNode->val;
    }

    void put(int key, int value) {
        if (mp.find(key) != mp.end()) {
            Node* curr = mp[key];
            deleteNode(curr);
            mp.erase(key);
        }
        if (mp.size() == capacity) {
            mp.erase(tail->prev->key);
            deleteNode(tail->prev);
        }
        Node* newNode = new Node(key, value);
        addNode(newNode);
        mp[key] = head->next;
    }
};

int main() {
    LRUCache lru(2);
    lru.put(1, 1);
    lru.put(2, 2);
    cout << lru.get(1) << endl; // returns 1
    lru.put(3, 3); // evicts key 2
    cout << lru.get(2) << endl; // returns -1 (not found)
    return 0;
}

