code.src:
#include <iostream>
#include <vector>
#include <cstdlib>
#include <ctime>
using namespace std;

class SkipList {
    struct Node {
        int val;
        vector<Node*> forward;
        Node(int val, int level) : val(val), forward(level, nullptr) {}
    };

    int MAX_LEVEL;
    float P;
    Node* head;
    int randomLevel() {
        int lvl = 1;
        while (((double)rand() / RAND_MAX) < P && lvl < MAX_LEVEL)
            lvl++;
        return lvl;
    }

public:
    SkipList(int maxLvl = 4, float p = 0.5) {
        MAX_LEVEL = maxLvl;
        P = p;
        head = new Node(-1, MAX_LEVEL);
        srand(time(0));
    }

    bool search(int target) {
        Node* curr = head;
        for (int i = MAX_LEVEL - 1; i >= 0; i--) {
            while (curr->forward[i] && curr->forward[i]->val < target) {
                curr = curr->forward[i];
            }
        }
        curr = curr->forward[0];
        return curr && curr->val == target;
    }

    void insert(int val) {
        vector<Node*> update(MAX_LEVEL, nullptr);
        Node* curr = head;
        for (int i = MAX_LEVEL - 1; i >= 0; i--) {
            while (curr->forward[i] && curr->forward[i]->val < val) {
                curr = curr->forward[i];
            }
            update[i] = curr;
        }
        curr = curr->forward[0];
        if (!curr || curr->val != val) {
            int rlevel = randomLevel();
            Node* nnode = new Node(val, rlevel);
            for (int i = 0; i < rlevel; i++) {
                nnode->forward[i] = update[i]->forward[i];
                update[i]->forward[i] = nnode;
            }
        }
    }
};

int main() {
    SkipList sl;
    sl.insert(3);
    sl.insert(6);
    sl.insert(7);
    cout << (sl.search(6) ? "Found" : "Not Found") << endl;
    cout << (sl.search(2) ? "Found" : "Not Found") << endl;
    return 0;
}

