code.src:
#include <iostream>
using namespace std;

class Node {
public:
    int val;
    Node* next;
    Node* random;
    Node(int _val) {
        val = _val;
        next = nullptr;
        random = nullptr;
    }
};

Node* copyRandomList(Node* head) {
    if (!head) return nullptr;

    // Step 1: Insert copy of each node right after its original node
    Node* curr = head;
    while (curr) {
        Node* temp = curr->next;
        curr->next = new Node(curr->val);
        curr->next->next = temp;
        curr = temp;
    }

    // Step 2: Assign random pointers for the copied nodes
    curr = head;
    while (curr) {
        if (curr->random) {
            curr->next->random = curr->random->next;
        }
        curr = curr->next->next;
    }

    // Step 3: Restore original list and extract the copy list
    curr = head;
    Node* dummyHead = new Node(0);
    Node* copyCurr = dummyHead;

    while (curr) {
        copyCurr->next = curr->next;
        copyCurr = copyCurr->next;
        curr->next = curr->next->next;
        curr = curr->next;
    }

    return dummyHead->next;
}

int main() {
    Node* head = new Node(1);
    head->next = new Node(2);
    head->random = head->next;
    head->next->random = head->next;

    Node* cloned = copyRandomList(head);
    cout << "Original val: " << head->val << ", Cloned val: " << cloned->val << endl;
    cout << "Random pointer copied successfully!" << endl;
    return 0;
}

