    stack<int> st; // stores indices
    for (int i = 0; i < n; ++i) {
        // while current element is greater than stack top, it is the NG for those indices
        while (!st.empty() && arr[i] > arr[st.top()]) {
            ans[st.top()] = arr[i];
            st.pop();
        }
        st.push(i); // push current index
    }
    return ans;
}

