class TwoStacks {
    int* arr;
    int size;
    int top1, top2;
public:
    TwoStacks(int n) {
        size = n;
        arr = new int[n];
        top1 = -1;
        top2 = size;
    }
    void push1(int x) {
        if (top1 + 1 < top2) {
            arr[++top1] = x;
        } else {
            cout << "Stack Overflow\n";
        }
    }
    void push2(int x) {
        if (top1 + 1 < top2) {
            arr[--top2] = x;
        } else {
            cout << "Stack Overflow\n";
        }
    }
    int pop1() {
        if (top1 >= 0) return arr[top1--];
        return -1;
    }
    int pop2() {
        if (top2 < size) return arr[top2++];
        return -1;
    }
};

