            result += c;
        else if (c == '(')
            st.push('(');
        else if (c == ')') {
            while (!st.empty() && st.top() != '(') {
                result += st.top();
                st.pop();
            }
            if (!st.empty()) st.pop();
        }
        else {
            while (!st.empty() && precedence(c) <= precedence(st.top())) {
                result += st.top();
                st.pop();
            }
            st.push(c);
        }
    }
    while (!st.empty()) {
        result += st.top();
        st.pop();
    }
    return result;
}

string infixToPrefix(string infix) {
    reverse(infix.begin(), infix.end());
    for (int i = 0; i < infix.length(); i++) {
        if (infix[i] == '(') infix[i] = ')';
        else if (infix[i] == ')') infix[i] = '(';
    }
    string postfix = infixToPostfix(infix);
    reverse(postfix.begin(), postfix.end());
    return postfix;
}

int main() {
    string exp = "(A-B/C)*(A/K-L)";
    cout << "Prefix: " << infixToPrefix(exp) << endl;
    return 0;
}

#include <iostream>
#include <stack>
#include <string>
using namespace std;

int evaluatePostfix(string exp) {
    stack<int> st;
    for (int i = 0; i < exp.length(); i++) {
        char c = exp[i];
        if (c == ' ' || c == ',') continue;
        // If operand, push to stack (converting char to int)
        if (isdigit(c)) {
            st.push(c - '0');
        }
        else {
            int val2 = st.top(); st.pop(); // Right operand
            int val1 = st.top(); st.pop(); // Left operand
            switch (c) {
                case '+': st.push(val1 + val2); break;
                case '-': st.push(val1 - val2); break;
                case '*': st.push(val1 * val2); break;
                case '/': st.push(val1 / val2); break;
            }
        }
    }
    return st.top(); // Final answer
}

int main() {
    string exp = "231*+9-"; // Evaluates to: 2 + (3 * 1) - 9 = 5 - 9 = -4
    cout << "Evaluation Result: " << evaluatePostfix(exp) << endl;
    return 0;
}

