code.src:
#include <iostream>
using namespace std;

class CircularQueue {
    int *arr;
    int front, rear, capacity;
public:
    CircularQueue(int s) {
        capacity = s;
        arr = new int[capacity];
        front = rear = -1;
    }
    ~CircularQueue() { delete[] arr; }

    bool isFull() {
        return (rear + 1) % capacity == front;
    }

    bool isEmpty() {
        return front == -1;
    }

    void enqueue(int val) {
        if (isFull()) {
            cout << "Queue Overflow\n";
            return;
        }
        if (isEmpty()) {
            front = 0;
        }
        rear = (rear + 1) % capacity;
        arr[rear] = val;
        cout << val << " enqueued.\n";
    }

    int dequeue() {
        if (isEmpty()) {
            cout << "Queue Underflow\n";
            return -1;
        }
        int val = arr[front];
        if (front == rear) {
            // Queue has only one element, reset after removal
            front = rear = -1;
        } else {
            front = (front + 1) % capacity;
        }
        return val;
    }
};

int main() {
    CircularQueue q(3);
    q.enqueue(10);
    q.enqueue(20);
    q.enqueue(30);
    cout << q.dequeue() << " dequeued.\n";
    q.enqueue(40); // Wraps around successfully
    return 0;
}

