#include <iostream>
using namespace std;

struct Node {
    int data;
    Node* next;
    Node(int val) : data(val), next(nullptr) {}
};

class LinkedStack {
    Node* top;
public:
    LinkedStack() : top(nullptr) {}
    void push(int x) {
        Node* temp = new Node(x);
        temp->next = top;
        top = temp; // New node becomes top
    }
    int pop() {
        if (!top) return -1;
        int val = top->data;
        Node* temp = top;
        top = top->next;
        delete temp;
        return val;
    }
};

int main() {
    LinkedStack s;
    s.push(5);
    cout << s.pop() << endl;
    return 0;
}

