#include <iostream>
#include <vector>
using namespace std;

struct Node {
    int key, val;
    Node* next;
    Node(int k, int v) : key(k), val(v), next(nullptr) {}
};

class ChainingHashMap {
    int capacity;
    vector<Node*> table;
public:
    ChainingHashMap(int cap) : capacity(cap), table(cap, nullptr) {}

    void insert(int key, int val) {
        int idx = key % capacity;
        Node* curr = table[idx];
        while(curr) {
            if(curr->key == key) { curr->val = val; return; }
            curr = curr->next;
        }
        Node* newNode = new Node(key, val);
        newNode->next = table[idx]; // Insert at head for O(1)
        table[idx] = newNode;
    }
};

int main() {
    ChainingHashMap map(5);
    map.insert(10, 100); // 10 % 5 = 0
    map.insert(15, 200); // 15 % 5 = 0 (Collision resolved via chaining!)
    cout << "Collision handled successfully.";
    return 0;
}

