#include <iostream>
#include <vector>
using namespace std;

class LinearProbingMap {
    int capacity, size;
    vector<int> keys, vals;
    const int EMPTY = -1;
public:
    LinearProbingMap(int cap) : capacity(cap), size(0), keys(cap, EMPTY), vals(cap, 0) {}

    bool insert(int k, int v) {
        if (size >= capacity) return false; // Table full
        int idx = k % capacity;
        int i = 0;
        while (keys[idx] != EMPTY && keys[idx] != k) {
            i++;
            idx = (k + i) % capacity; // Linear probe step
        }
        if (keys[idx] == EMPTY) size++;
        keys[idx] = k;
        vals[idx] = v;
        return true;
    }
};

int main() {
    LinearProbingMap m(7);
    m.insert(10, 100);
    m.insert(17, 200); // 17 % 7 = 3, but 10 % 7 = 3 -> Probed to next slot!
    cout << "Open addressing insert successful.";
    return 0;
}

