public:
    ConsistentHashing(int numReplicas = 3) : replicas(numReplicas) {}

    void addNode(const std::string& node) {
        for (int i = 0; i < replicas; ++i) {
            std::string replicaKey = node + "#" + std::to_string(i);
            size_t hashVal = hashFunction(replicaKey);
            ring[hashVal] = node;
        }
    }

    void removeNode(const std::string& node) {
        for (int i = 0; i < replicas; ++i) {
            std::string replicaKey = node + "#" + std::to_string(i);
            size_t hashVal = hashFunction(replicaKey);
            ring.erase(hashVal);
        }
    }

    std::string getServer(const std::string& key) {
        if (ring.empty()) return "";
        size_t hashVal = hashFunction(key);
        auto it = ring.lower_bound(hashVal);
        if (it == ring.end()) {
            return ring.begin()->second;
        }
        return it->second;
    }
};

int main() {
    ConsistentHashing ch(3);
    ch.addNode("ServerA");
    ch.addNode("ServerB");
    ch.addNode("ServerC");

    std::cout << "Key 'user123' maps to: " << ch.getServer("user123") << std::endl;
    std::cout << "Key 'video456' maps to: " << ch.getServer("video456") << std::endl;
    return 0;
}

