#include <iostream>
#include <vector>
#include <string>

class BloomFilter {
private:
    std::vector<bool> bits;
    size_t size;
    int numHashFuncs;

    // Simple hash functions for demonstration
    size_t hash1(const std::string& s) const {
        size_t h = 0;
        for (char c : s) h = 31 * h + c;
        return h % size;
    }

    size_t hash2(const std::string& s) const {
        size_t h = 0;
        for (char c : s) h = 33 * h + c;
        return h % size;
    }

public:
    BloomFilter(size_t sz, int k) : size(sz), numHashFuncs(k), bits(sz, false) {}

    void insert(const std::string& item) {
        bits[hash1(item)] = true;
        bits[hash2(item)] = true;
    }

    bool contains(const std::string& item) const {
        return bits[hash1(item)] && bits[hash2(item)];
    }
};

int main() {
    BloomFilter bf(100, 2);
    bf.insert("apple");
    bf.insert("banana");

    std::cout << std::boolalpha;
    std::cout << "Contains 'apple': " << bf.contains("apple") << std::endl;   // True
    std::cout << "Contains 'grape': " << bf.contains("grape") << std::endl;   // False (usually)
    return 0;
}

