public:
    void serialize(TreeNode* root, ostringstream& out) {
        if (!root) {
            out << "# ";
            return;
        }
        out << root->val << " ";
        serialize(root->left, out);
        serialize(root->right, out);
    }

    string serialize(TreeNode* root) {
        ostringstream out;
        serialize(root, out);
        return out.str();
