struct GNode {                // node of general tree
    int data;
    vector<GNode*> children;
    GNode(int v) : data(v) {}
};

struct BNode {                // node of binary (LCRS) tree
    int data;
    BNode *left, *right;      // left = first child, right = next sibling
    BNode(int v) : data(v), left(nullptr), right(nullptr) {}
};

// Convert general tree rooted at g to binary LCRS tree
BNode* convert(GNode* g) {
    if (!g) return nullptr;
    BNode* b = new BNode(g->data);
    if (!g->children.empty()) {
        // first child becomes left child
        b->left = convert(g->children[0]);
        // remaining children become right siblings of the first child
        BNode* sibling = b->left;
        for (size_t i = 1; i < g->children.size(); ++i) {
            sibling->right = convert(g->children[i]);
            sibling = sibling->right;
        }
    }
    return b;
}

// Preorder traversal of LCRS binary tree (visits nodes in original tree order)
void preorderLCRS(BNode* root) {
    if (!root) return;
    cout << root->data << " ";
    preorderLCRS(root->left);   // first child subtree
    preorderLCRS(root->right);  // next sibling subtree
}

int main() {
    // Build a sample general tree:
    //        1
    //      / | \
    //     2  3  4
    //        / \
    //       5   6
    GNode* r = new GNode(1);
    r->children.push_back(new GNode(2));
    GNode* n3 = new GNode(3);
    n3->children.push_back(new GNode(5));
    n3->children.push_back(new GNode(6));
    r->children.push_back(n3);
    r->children.push_back(new GNode(4));

    BNode* binaryRoot = convert(r);
    cout << "Preorder of LCRS binary tree: ";
    preorderLCRS(binaryRoot);
    cout << "\n";
    return 0;
}

