vector<int> topView(TreeNode* root) {
    vector<int> ans;
    if (!root) return ans;
    map<int, int> mp;
    queue<pair<TreeNode*, int>> q;
    q.push({root, 0});

    while (!q.empty()) {
        auto it = q.front();
        q.pop();
        TreeNode* node = it.first;
        int hd = it.second;

        // If HD not present in map, insert the first node at this HD
        if (mp.find(hd) == mp.end()) {
