#include <bits/stdc++.h>
using namespace std;

struct Node {
    int key;
    Node *left, *right;
    Node(int k): key(k), left(nullptr), right(nullptr) {}
};

// Right rotation
Node* rotateRight(Node* x){
    Node* y = x->left;
    x->left = y->right;
    y->right = x;
    return y; // new root of this subtree
}
// Left rotation
Node* rotateLeft(Node* x){
    Node* y = x->right;
    x->right = y->left;
    y->left = x;
    return y;
}

// Splay operation – brings key to root (or last accessed node)
Node* splay(Node* root, int key){
    if(!root || root->key == key) return root;
    // Key in left subtree
    if(key < root->key){
        if(!root->left) return root; // not found
        // Zig‑Zig (Left Left)
        if(key < root->left->key){
            root->left->left = splay(root->left->left, key);
            root = rotateRight(root);
        }
        // Zig‑Zag (Left Right)
        else if(key > root->left->key){
            root->left->right = splay(root->left->right, key);
            if(root->left->right) root->left = rotateLeft(root->left);
        }
        return (root->left) ? rotateRight(root) : root;
    }
    else { // key > root->key, right subtree
        if(!root->right) return root;
        // Zig‑Zig (Right Right)
        if(key > root->right->key){
            root->right->right = splay(root->right->right, key);
            root = rotateLeft(root);
        }
        // Zig‑Zag (Right Left)
        else if(key < root->right->key){
            root->right->left = splay(root->right->left, key);
            if(root->right->left) root->right = rotateRight(root->right);
        }
        return (root->right) ? rotateLeft(root) : root;
    }
}

Node* insert(Node* root, int key){
    if(!root) return new Node(key);
    root = splay(root, key);
    if(root->key == key) return root; // duplicate, ignore
    Node* n = new Node(key);
    if(key < root->key){
        n->right = root;
        n->left = root->left;
        root->left = nullptr;
    } else {
        n->left = root;
        n->right = root->right;
        root->right = nullptr;
    }
    return n; // new root
}

void inorder(Node* r){ if(!r) return; inorder(r->left); cout<<r->key<<' '; inorder(r->right); }

int main(){
    Node* root = nullptr;
    vector<int> vals = {100, 50, 200, 40, 30, 20};
    for(int v: vals) root = insert(root, v);
    cout << "Inorder after inserts: "; inorder(root); cout << "\n";
    root = splay(root, 30); // access 30 -> becomes root
    cout << "Root after splaying 30: " << root->key << "\n";
    return 0;
}

