#include <iostream>
using namespace std;

struct Node {
    int data;
    Node *left, *right;
    bool lThread, rThread;
};

Node* insert(Node* root, int key) {
    Node* ptr = root;
    Node* parent = nullptr;
    while (ptr != nullptr) {
        if (key == ptr->data) return root;
        parent = ptr;
        if (key < ptr->data) {
            if (!ptr->lThread) ptr = ptr->left;
            else break;
        } else {
            if (!ptr->rThread) ptr = ptr->right;
            else break;
        }
    }
    Node* tmp = new Node{key, nullptr, nullptr, true, true};
    if (parent == nullptr) {
        root = tmp;
    } else if (key < parent->data) {
        tmp->left = parent->left;
        tmp->right = parent;
        parent->lThread = false;
        parent->left = tmp;
    } else {
        tmp->left = parent;
        tmp->right = parent->right;
        parent->rThread = false;
        parent->right = tmp;
    }
    return root;
}

int main() {
    Node* root = nullptr;
    root = insert(root, 20);
    root = insert(root, 10);
    root = insert(root, 30);
    cout << "Threaded BST created successfully.\n";
    return 0;
}

