struct Node {
    char data;
    Node *left, *right;
};

Node* createNode(char val) {
    return new Node{val, nullptr, nullptr};
}

Node* buildExpressionTree(string postfix) {
    stack<Node*> st;
    for (char c : postfix) {
        if (isalnum(c)) {
            st.push(createNode(c));
        } else {
            Node* t = createNode(c);
            t->right = st.top(); st.pop(); // Note: right child popped first
            t->left = st.top(); st.pop();
            st.push(t);
        }
    }
    return st.top();
}

void postOrder(Node* root) {
    if (root) {
        postOrder(root->left);
        postOrder(root->right);
        cout << root->data << " ";
    }
}

int main() {
    string postfix = "ab+c*";
    Node* root = buildExpressionTree(postfix);
    cout << "Postorder traversal: ";
    postOrder(root);
    return 0;
}

