#include <bits/stdc++.h>
using namespace std;

struct SegTree {
    int n;                // size of original array
    vector<long long> tree, lazy;
    SegTree(const vector<int>& a) {
        n = a.size();
        tree.assign(4*n, 0);
        lazy.assign(4*n, 0);
        build(1,0,n-1,a);
    }
    void build(int node,int l,int r,const vector<int>& a){
        if(l==r){ tree[node]=a[l]; return; }
        int mid=(l+r)/2;
        build(node*2,l,mid,a);
        build(node*2+1,mid+1,r,a);
        tree[node]=tree[node*2]+tree[node*2+1]; // sum merge
    }
    void push(int node,int l,int r){ // propagate lazy value
        if(lazy[node]!=0){
            tree[node]+= (r-l+1)*lazy[node]; // apply to current segment
            if(l!=r){ // not leaf
                lazy[node*2]   += lazy[node];
                lazy[node*2+1] += lazy[node];
            }
            lazy[node]=0;
        }
    }
    void updateRange(int L,int R,long long val){ updateRange(1,0,n-1,L,R,val); }
    void updateRange(int node,int l,int r,int L,int R,long long val){
        push(node,l,r);
        if(r<L || R<l) return; // no overlap
        if(L<=l && r<=R){ // total overlap
            lazy[node]+=val;
            push(node,l,r);
            return;
        }
        int mid=(l+r)/2;
        updateRange(node*2,l,mid,L,R,val);
        updateRange(node*2+1,mid+1,r,L,R,val);
        tree[node]=tree[node*2]+tree[node*2+1];
    }
    long long query(int L,int R){ return query(1,0,n-1,L,R); }
    long long query(int node,int l,int r,int L,int R){
        push(node,l,r);
        if(r<L || R<l) return 0; // no overlap
        if(L<=l && r<=R) return tree[node]; // total overlap
        int mid=(l+r)/2;
        return query(node*2,l,mid,L,R)+query(node*2+1,mid+1,r,L,R);
    }
};

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    vector<int> arr = {1,3,5,7,9,11};
    SegTree st(arr);
    cout << st.query(1,3) << "\n"; // sum 3+5+7 = 15
    st.updateRange(1,4,10); // add 10 to indices 1..4
    cout << st.query(1,3) << "\n"; // (3+10)+(5+10)+(7+10)=45
    return 0;
}

#include <iostream>
#include <queue>
#include <vector>

using namespace std;

class MedianFinder {
    priority_queue<int> maxHeap; // lower half
    priority_queue<int, vector<int>, greater<int>> minHeap; // upper half
public:
    void addNum(int num) {
        maxHeap.push(num);
        minHeap.push(maxHeap.top());
        maxHeap.pop();

        if (minHeap.size() > maxHeap.size()) {
            maxHeap.push(minHeap.top());
            minHeap.pop();
        }
    }

    double findMedian() {
        if (maxHeap.size() > minHeap.size()) {
            return maxHeap.top();
        }
        return (maxHeap.top() + minHeap.top()) / 2.0; // Important: 2.0 for double division
    }
};

int main() {
    MedianFinder mf;
    mf.addNum(1);
    mf.addNum(2);
    cout << mf.findMedian() << endl; // Output: 1.5
    mf.addNum(3);
    cout << mf.findMedian() << endl; // Output: 2
    return 0;
}

