code.src:
#include <iostream>
#include <vector>
#include <queue>

using namespace std;

struct ListNode {
    int val;
    ListNode* next;
    ListNode(int x) : val(x), next(nullptr) {}
};

struct Compare {
    bool operator()(ListNode* a, ListNode* b) {
        return a->val > b->val; // Min-heap based on node value
    }
};

class Solution {
public:
    ListNode* mergeKLists(vector<ListNode*>& lists) {
        priority_queue<ListNode*, vector<ListNode*>, Compare> minHeap;

        for (auto l : lists) {
            if (l) minHeap.push(l);
        }

        ListNode dummy(0);
        ListNode* tail = &dummy;

        while (!minHeap.empty()) {
            ListNode* curr = minHeap.top();
            minHeap.pop();
            tail->next = curr;
            tail = tail->next;

            if (curr->next) {
                minHeap.push(curr->next); // Push next node from the same list
            }
        }
        tail->next = nullptr;
        return dummy.next;
    }
};

int main() {
    ListNode* l1 = new ListNode(1); l1->next = new ListNode(4);
    ListNode* l2 = new ListNode(2); l2->next = new ListNode(5);
    vector<ListNode*> lists = {l1, l2};
    Solution sol;
    ListNode* res = sol.mergeKLists(lists);
    while(res) { cout << res->val << " "; res = res->next; }
    return 0;
}

