        TrieNode() {
            isEnd = false;
            for(int i = 0; i < 26; i++) children[i] = nullptr;
        }
    };
    TrieNode* root;
public:
    Trie() {
        root = new TrieNode();
    }

    void insert(string word) {
        TrieNode* curr = root;
        for (char c : word) {
            int idx = c - 'a';
            if (!curr->children[idx]) {
                curr->children[idx] = new TrieNode();
            }
            curr = curr->children[idx];
        }
        curr->isEnd = true; // Mark end of word
    }

    bool search(string word) {
        TrieNode* curr = root;
        for (char c : word) {
            int idx = c - 'a';
            if (!curr->children[idx]) return false;
            curr = curr->children[idx];
        }
        return curr->isEnd;
    }

    bool startsWith(string prefix) {
        TrieNode* curr = root;
        for (char c : prefix) {
            int idx = c - 'a';
            if (!curr->children[idx]) return false;
            curr = curr->children[idx];
        }
        return true;
    }
};

int main() {
    Trie t;
    t.insert("apple");
    cout << t.search("apple") << endl;   // Output: 1 (true)
    cout << t.search("app") << endl;     // Output: 0 (false)
    cout << t.startsWith("app") << endl; // Output: 1 (true)
    return 0;
}

