code.src:
#include <iostream>
#include <vector>
using namespace std;

class LazySegmentTree {
    int n;
    vector<long long> tree, lazy;

    void push(int node, int start, int end) {
        if (lazy[node] != 0) {
            int mid = (start + end) / 2;
            // Apply to left child
            tree[2 * node] += lazy[node] * (mid - start + 1);
            lazy[2 * node] += lazy[node];
            // Apply to right child
            tree[2 * node + 1] += lazy[node] * (end - mid);
            lazy[2 * node + 1] += lazy[node];
            // Clear current lazy
            lazy[node] = 0;
        }
    }

public:
    LazySegmentTree(int sz) {
        n = sz;
        tree.assign(4 * n, 0);
        lazy.assign(4 * n, 0);
    }

    void updateRange(int node, int start, int end, int l, int r, long long val) {
        if (r < start || end < l) return;
        if (l <= start && end <= r) {
            tree[node] += val * (end - start + 1);
            lazy[node] += val; // Storing the deferred update
            return;
        }
        push(node, start, end); // Crucial: push before going down
        int mid = (start + end) / 2;
        updateRange(2 * node, start, mid, l, r, val);
        updateRange(2 * node + 1, mid + 1, end, l, r, val);
        tree[node] = tree[2 * node] + tree[2 * node + 1];
    }

    long long queryRange(int node, int start, int end, int l, int r) {
        if (r < start || end < l) return 0;
        if (l <= start && end <= r) return tree[node];
        push(node, start, end);
        int mid = (start + end) / 2;
        return queryRange(2 * node, start, mid, l, r) + queryRange(2 * node + 1, mid + 1, end, l, r);
    }
};

int main() {
    LazySegmentTree st(5);
    st.updateRange(1, 0, 4, 1, 3, 10); // Add 10 to indices 1 to 3
    cout << "Sum (1 to 3): " << st.queryRange(1, 0, 4, 1, 3) << endl;
    return 0;
}

