#include <iostream>
#include <vector>
using namespace std;

class FenwickTree {
    int n;
    vector<long long> bit;
public:
    FenwickTree(int size) {
        n = size;
        bit.assign(n + 1, 0);
    }

    void add(int idx, long long val) {
        for (++idx; idx <= n; idx += idx & -idx)
            bit[idx] += val;
    }

    long long query(int idx) {
        long long sum = 0;
        for (++idx; idx > 0; idx -= idx & -idx)
            sum += bit[idx];
        return sum;
    }

    long long rangeQuery(int l, int r) {
        return query(r) - query(l - 1);
    }
};

int main() {
    FenwickTree ft(5);
    ft.add(0, 5); // A[0] = 5
    ft.add(2, 3); // A[2] = 3
    ft.add(4, 2); // A[4] = 2
    cout << "Sum from index 0 to 4: " << ft.rangeQuery(0, 4) << endl;
    return 0;
}

#include <iostream>
#include <vector>
#include <cmath>
using namespace std;

class SparseTable {
    int n, K;
    vector<vector<int>> st;
    vector<int> logs;
public:
    SparseTable(const vector<int>& arr) {
        n = arr.size();
        K = log2(n) + 1;
        st.assign(K, vector<int>(n));
        logs.assign(n + 1, 0);

        for (int i = 2; i <= n; i++)
            logs[i] = logs[i / 2] + 1;

        for (int i = 0; i < n; i++)
            st[0][i] = arr[i];

        for (int k = 1; k < K; k++) {
            for (int i = 0; i + (1 << k) <= n; i++) {
                st[k][i] = min(st[k - 1][i], st[k - 1][i + (1 << (k - 1))]);
            }
        }
    }

    int query(int L, int R) {
        int k = logs[R - L + 1];
        return min(st[k][L], st[k][R - (1 << k) + 1]);
    }
};

int main() {
    vector<int> arr = {3, 1, 5, 2, 8, 6};
    SparseTable st(arr);
    cout << "Minimum between index 1 and 4: " << st.query(1, 4) << endl;
    return 0;
}

