bool dfsUndirected(int v, int parent, const vector<vector<int>>& adj, vector<int>& vis){
    vis[v] = 1; // visited
    for(int nb : adj[v]){
        if(!vis[nb]){
            if(dfsUndirected(nb, v, adj, vis)) return true;
        } else if(nb != parent){ // visited neighbour not parent => cycle
            return true;
        }
