// ---------- Directed Cycle Detection (colour method) ----------
enum Colour{WHITE, GRAY, BLACK};
bool dfsDirected(int v, const vector<vector<int>>& adj, vector<Colour>& col){
    col[v] = GRAY; // currently exploring
    for(int nb : adj[v]){
        if(col[nb]==GRAY) return true; // back edge -> cycle
        if(col[nb]==WHITE && dfsDirected(nb,adj,col)) return true;
    }
    col[v] = BLACK; // finished
    return false;
}

