struct DSU {
    vector<int> parent, rank;
    DSU(int n) { parent.resize(n); rank.assign(n, 0); iota(parent.begin(), parent.end(), 0); }
    int find(int i) { if (parent[i] == i) return i; return parent[i] = find(parent[i]); }
    void unite(int i, int j) { /* merge roots based on rank */ }
};

code.src:
#include <iostream>
#include <vector>
#include <numeric>

using namespace std;

class DSU {
    vector<int> parent, rank;
public:
    DSU(int n) {
        parent.resize(n);
        rank.assign(n, 0);
        iota(parent.begin(), parent.end(), 0); // parent[i] = i
    }

    int find(int i) {
        if (parent[i] == i)
            return i;
        return parent[i] = find(parent[i]); // Path compression
    }

    void unite(int i, int j) {
        int root_i = find(i);
        int root_j = find(j);
        if (root_i != root_j) {
            if (rank[root_i] < rank[root_j]) {
                parent[root_i] = root_j;
            } else if (rank[root_i] > rank[root_j]) {
                parent[root_j] = root_i;
            } else {
                parent[root_j] = root_i;
                rank[root_i]++;
            }
        }
    }
};

int main() {
    DSU dsu(5);
    dsu.unite(0, 1);
    dsu.unite(1, 2);
    cout << (dsu.find(0) == dsu.find(2) ? "Connected" : "Not Connected") << endl;
    return 0;
}

