#include <bits/stdc++.h>
using namespace std;

bool checkBipartite(int V, vector<vector<int>>& adj) {
    vector<int> color(V, -1);
    for (int i = 0; i < V; i++) {
        if (color[i] == -1) {
            queue<int> q;
            q.push(i);
            color[i] = 0;
            while (!q.empty()) {
                int u = q.front();
                q.pop();
                for (int v : adj[u]) {
                    if (color[v] == -1) {
                        color[v] = 1 - color[u]; // Alternate color
                        q.push(v);
                    } else if (color[v] == color[u]) {
                        return false; // Conflict found
                    }
                }
            }
        }
    }
    return true;
}

int main() {
    int V = 4;
    vector<vector<int>> adj = {{1, 3}, {0, 2}, {1, 3}, {0, 2}};
    if (checkBipartite(V, adj)) cout << "Graph is Bipartite\n";
    else cout << "Graph is NOT Bipartite\n";
    return 0;
}

