        pq.pop();
        if(dis > dist[u]) continue;
        auto it : adj[u]) {
            int v = it.first; int weight = it.second;
            if(dist[u] + weight < dist[v]) {
                dist[v] = dist[u] + weight;
                pq.push({dist[v], v});
            }
        }
    }
    return dist;
}

