const int INF = 1e9;

void zeroOneBFS(int V, int src, const vector<vector<pair<int, int>>>& adj) {
    vector<int> dist(V, INF);
    deque<int> dq;

    dist[src] = 0;
    dq.push_front(src);

    while (!dq.empty()) {
        int u = dq.front();
        dq.pop_front();

        for (auto& edge : adj[u]) {
            int v = edge.first;
            int weight = edge.second;

            if (dist[u] + weight < dist[v]) {
                dist[v] = dist[u] + weight;
                if (weight == 0) {
                    dq.push_front(v); // 0-weight goes to front
                } else {
                    dq.push_back(v);  // 1-weight goes to back
                }
            }
        }
    }

    for (int i = 0; i < V; ++i) {
        cout << "Node " << i << " Distance: " << dist[i] << "\n";
    }
}

