typedef pair<int, int> pii;

int primMST(int V, vector<vector<pii>>& adj) {
    priority_queue<pii, vector<pii>, greater<pii>> pq;
    vector<bool> visited(V, false);
    int mstWeight = 0;

    pq.push({0, 0}); // {weight, vertex}

    while(!pq.empty()) {
        auto p = pq.top();
        pq.pop();

        int u = p.second;
        int weight = p.first;

        if(visited[u]) continue;
        visited[u] = true;
        mstWeight += weight;

        for(auto& edge : adj[u]) {
            int v = edge.first;
            int wt = edge.second;
            if(!visited[v]) {
                pq.push({wt, v});
            }
        }
    }
    return mstWeight;
}

