    for(int i=0;i<n;++i)
        for(int j=0;j<n;++j) cin>>dist[i][j];
    const long long INF = 4e18;
    int N = 1<<n;
    vector<vector<long long>> dp(N, vector<long long>(n, INF));
    dp[1<<0][0] = 0; // start at city 0
    for(int mask=0; mask<N; ++mask){
        for(int u=0; u<n; ++u){
            if(!(mask & (1<<u))) continue; // u not in mask
            long long cur = dp[mask][u];
            if(cur==INF) continue;
            for(int v=0; v<n; ++v){
                if(mask & (1<<v)) continue; // already visited
                int nmask = mask | (1<<v);
                dp[nmask][v] = min(dp[nmask][v], cur + dist[u][v]);
            }
        }
    }
    long long ans = INF;
    int full = N-1;
    for(int i=0;i<n;++i){
        ans = min(ans, dp[full][i] + dist[i][0]); // return to start
    }
    cout<<ans<<"\n";
    return 0;
}
