#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>

using namespace std;

const int INF = 1e9;

// BFS to find augmenting path in residual graph
bool bfs(int s, int t, int n, vector<vector<int>>& capacity, vector<vector<int>>& adj, vector<int>& parent) {
    fill(parent.begin(), parent.end(), -1);
    parent[s] = -2;
    queue<pair<int, int>> q;
    q.push({s, INF});

    while (!q.empty()) {
        int u = q.front().first;
        int flow = q.front().second;
        q.pop();

        for (int next : adj[u]) {
            if (parent[next] == -1 && capacity[u][next] > 0) {
                parent[next] = u;
                int new_flow = min(flow, capacity[u][next]);
                if (next == t)
                    return true;
                q.push({next, new_flow});
            }
        }
    }
    return false;
}

// Edmonds-Karp Algorithm for Max Flow
int edmondsKarp(int s, int t, int n, vector<vector<int>>& capacity, vector<vector<int>>& adj) {
    int flow = 0;
    vector<int> parent(n);
    while (bfs(s, t, n, capacity, adj, parent)) {
        int push = INF;
        for (int v = t; v != s; v = parent[v]) {
            int u = parent[v];
            push = min(push, capacity[u][v]);
        }
        for (int v = t; v != s; v = parent[v]) {
            int u = parent[v];
            capacity[u][v] -= push; // Decrease forward capacity
            capacity[v][u] += push; // Increase reverse capacity
        }
        flow += push;
    }
    return flow;
}

int main() {
    int n = 4;
    vector<vector<int>> adj(n);
    vector<vector<int>> capacity(n, vector<int>(n, 0));
    auto add_edge = [&](int u, int v, int cap) {
        adj[u].push_back(v);
        adj[v].push_back(u);
        capacity[u][v] += cap;
    };
    add_edge(0, 1, 3);
    add_edge(0, 2, 3);
    add_edge(1, 2, 2);
    add_edge(1, 3, 3);
    add_edge(2, 3, 2);
    cout << "Max Flow: " << edmondsKarp(0, 3, n, capacity, adj) << endl;
    return 0;
}

