        if(nums[mid] == target) { last = mid; low = mid + 1; }
        else if(nums[mid] < target) low = mid + 1;
        else high = mid - 1;
    }
    return {first, last};
}

int countFreq(vector<int>& arr, int target) {
    int first = firstOccurrence(arr, target);
    if (first == -1) return 0;
    int last = lastOccurrence(arr, target);
    return last - first + 1;
}

