// Ternary search for maximum
double ternarySearch(double low, double high) {
    for (int i = 0; i < 100; i++) { // 100 iterations guarantee high precision
        double m1 = low + (high - low) / 3.0;
        double m2 = high - (high - low) / 3.0;

        if (f(m1) < f(m2)) {
            low = m1; // Peak is in [m1, high]
        } else {
            high = m2; // Peak is in [low, m2]
        }
    }
    return (low + high) / 2.0;
}

