void shellSort(vector<int>& a) {
    int n = a.size();
    // Tokuda gap sequence – good practical performance
    for (int gap = n/2; gap > 0; gap /= 2) {
        for (int i = gap; i < n; ++i) {
            int temp = a[i];
            int j = i;
            // gapped insertion sort
            while (j >= gap && a[j - gap] > temp) {
                a[j] = a[j - gap];
                j -= gap;
            }
            a[j] = temp; // place key at its correct gapped position
        }
    }
}

