using namespace std;

int maxActivities(vector<pair<int,int>> activities) {
    // 1. sort by finish time
    sort(activities.begin(), activities.end(),
        [](const auto &a, const auto &b){ return a.second < b.second; });
    int count = 0;
    int lastFinish = INT_MIN; // nothing selected yet
    for (auto &act : activities) {
        if (act.first >= lastFinish) { // compatible
            ++count;
            lastFinish = act.second; // update finish time
        }
    }
    return count;
}

int main(){
    vector<pair<int,int>> act = {{1,4},{3,5},{0,6},{5,7},{3,9},{5,9},{6,10},{8,11},{8,12},{2,14},{12,16}};
    cout << "Maximum activities: " << maxActivities(act) << "\n"; // expected 4
    return 0;
}

