#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

struct Item {
    int value, weight;
};

bool cmp(struct Item a, struct Item b) {
    double r1 = (double)a.value / a.weight;
    double r2 = (double)b.value / b.weight;
    return r1 > r2;
}

double fractionalKnapsack(int W, vector<Item>& arr) {
    sort(arr.begin(), arr.end(), cmp);
    double finalValue = 0.0;
    for (auto& item : arr) {
        if (item.weight <= W) {
            W -= item.weight;
            finalValue += item.value;
        } else {
            finalValue += item.value * ((double)W / item.weight);
            break;
        }
    }
    return finalValue;
}

int main() {
    vector<Item> arr = {{60, 10}, {100, 20}, {120, 30}};
    int W = 50;
    cout << "Maximum value: " << fractionalKnapsack(W, arr);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Job {
    char id;        // job identifier
    int profit;     // profit if job is completed
    int deadline;   // deadline (1‑based)
};

// Greedy job sequencing
pair<int,int> jobSequencing(vector<Job> jobs) {
    // 1. sort by profit descending
    sort(jobs.begin(), jobs.end(), [](const Job& a, const Job& b){
        return a.profit > b.profit;
    });
    // 2. find maximum deadline
    int maxSlot = 0;
    for (auto &j: jobs) maxSlot = max(maxSlot, j.deadline);
    vector<int> slot(maxSlot+1, -1); // 0 unused, -1 means free
    int count = 0, totalProfit = 0;
    // 3. place each job
    for (auto &j: jobs) {
        for (int s = min(j.deadline, maxSlot); s >= 1; --s) {
            if (slot[s] == -1) { // free slot found
                slot[s] = j.id;   // assign job id to slot
                count++; totalProfit += j.profit;
                break;
            }
        }
    }
    return {count, totalProfit};
}

int main(){
    vector<Job> jobs = {{'a', 100, 2}, {'b', 19, 1}, {'c', 27, 2}, {'d', 25, 1}, {'e', 15, 3}};
    auto res = jobSequencing(jobs);
    cout << "Jobs done: " << res.first << ", Total profit: " << res.second << "\n";
    return 0;
}

