#include <iostream>
#include <queue>
#include <string>
using namespace std;

struct MinNode {
    char data;
    unsigned freq;
    MinNode *left, *right;
    MinNode(char data, unsigned freq) : data(data), freq(freq), left(nullptr), right(nullptr) {}
};

struct Compare {
    bool operator()(MinNode* l, MinNode* r) {
        return l->freq > r->freq;
    }
};

void printCodes(MinNode* root, string str) {
    if (!root) return;
    if (root->data != '$') cout << root->data << ": " << str << "\n";
    printCodes(root->left, str + "0");
    printCodes(root->right, str + "1");
}

int main() {
    char arr[] = {'a', 'b', 'c', 'd'};
    int freq[] = {5, 9, 12, 13};
    priority_queue<MinNode*, vector<MinNode*>, Compare> minHeap;
    for (int i = 0; i < 4; ++i) minHeap.push(new MinNode(arr[i], freq[i]));
    while (minHeap.size() > 1) {
        MinNode *left = minHeap.top(); minHeap.pop();
        MinNode *right = minHeap.top(); minHeap.pop();
        MinNode *sum = new MinNode('$', left->freq + right->freq);
        sum->left = left; sum->right = right;
        minHeap.push(sum);
    }
    printCodes(minHeap.top(), "");
    return 0;
}

