#include <iostream>
#include <vector>
#include <algorithm>
using

int climbStairs(int n) {
    if (n <= 2) return n;
    int prev2 = 1, prev1 = 2;
    for (int i = 3; i <= n; ++i) {
        int curr = prev1 + prev2; // Recurrence relation
        prev2 = prev1;
        prev1 = curr;
    }
    return prev1;
}

int rob(std::vector<int>& nums) {
    int n = nums.size();
    if (n == 0) return 0;
    if (n == 1) return nums[0];
    int prev2 = nums[0];
    int prev1 = std::max(nums[0], nums[1]);
    for (int i = 2; i < n; ++i) {
        int curr = std::max(prev1, prev2 + nums[i]); // Skip vs Take
        prev2 = prev1;
        prev1 = curr;
    }
    return prev1;
}

int main() {
    std::cout << "Stairs (5): " << climbStairs(5) << "\n";
    std::vector<int> houses = {2, 7, 9, 3, 1};
    std::cout << "Robbed: " << rob(houses) << "\n";
    return 0;
}

