// Matrix Chain Multiplication – returns minimum scalar multiplications
int matrixChainOrder(const vector<int>& p) {
    int n = (int)p.size() - 1;               // number of matrices
    vector<vector<int>> dp(n+1, vector<int>(n+1, 0));
    vector<vector<int>> split(n+1, vector<int>(n+1, 0)); // optional for reconstruction

    // L = chain length
    for (int L = 2; L <= n; ++L) {
        for (int i = 1; i <= n - L + 1; ++i) {
            int j = i + L - 1;
            dp[i][j] = INT_MAX;
            for (int k = i; k < j; ++k) {
                int cost = dp[i][k] + dp[k+1][j] + p[i-1]*p[k]*p[j];
                if (cost < dp[i][j]) {
                    dp[i][j] = cost;
                    split[i][j] = k; // store split point
                }
            }
        }
    }
    // Uncomment to print optimal parenthesization
