#include <iostream>
#include <string>
#include <vector>
#include <algorithm>

using namespace std;

int minDistance(string word1, string word2) {
    int n = word1.length(), m = word2.length();
    vector<vector<int>> dp(n + 1, vector<int>(m + 1));

    for (int i = 0; i <= n; ++i) dp[i][0] = i; // Deletions
    for (int j = 0; j <= m; ++j) dp[0][j] = j; // Insertions

    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= m; ++j) {
            if (word1[i - 1] == word2[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1];
            } else {
                dp[i][j] = 1 + min({dp[i - 1][j],     // Delete
                                    dp[i][j - 1],     // Insert
                                    dp[i - 1][j - 1]}); // Replace
            }
        }
    }
    return dp[n][m];
}

int main() {
    string w1 = "horse", w2 = "ros";
    cout << "Edit Distance: " << minDistance(w1, w2) << endl;
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int minPathSum(vector<vector<int>>& grid) {
    int m = grid.size(), n = grid[0].size();
    vector<vector<int>> dp(m, vector<int>(n, 0));

    dp[0][0] = grid[0][0];
    for (int j = 1; j < n; ++j) dp[0][j] = dp[0][j-1] + grid[0][j]; // Base case: first row
    for (int i = 1; i < m; ++i) dp[i][0] = dp[i-1][0] + grid[i][0]; // Base case: first col

    for (int i = 1; i < m; ++i) {
        for (int j = 1; j < n; ++j) {
            dp[i][j] = grid[i][j] + min(dp[i-1][j], dp[i][j-1]); // Transition relation
        }
    }
    return dp[m-1][n-1];
}

int main() {
    vector<vector<int>> grid = {{1,3,1},{1,5,1},{4,2,1}};
    cout << "Min Path Sum: " << minPathSum(grid) << endl;
    return 0;
}

