#include <iostream>
#include <vector>
#include <numeric>
using namespace std;

bool canPartition(vector<string>& args, vector<int>& nums) {
    int sum = accumulate(nums.begin(), nums.end(), 0);
    if (sum % 2 != 0) return false; // Odd sum cannot be partitioned equally
    int target = sum / 2;

    vector<bool> dp(target + 1, false);
    dp[0] = true; // Base case: target 0 is always achievable

    for (int num : nums) {
        // Traverse backwards to use each number at most once (0/1 Knapsack)
        for (int j = target; j >= num; --j) {
            dp[j] = dp[j] || dp[j - num];
        }
    }
    return dp[target];
}

int main() {
    vector<int> nums = {1, 5, 11, 5};
    vector<string> args;
    cout << (canPartition(args, nums) ? "Can Partition: True" : "Can Partition: False") << endl;
    return 0;
}

