#include <iostream>
#include <algorithm>
using namespace std;

struct TreeNode {
    int val;
    TreeNode *left, *right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

class Solution {
private:
    int maxSum = -1e9;
    int dfs(TreeNode* root) {
        if (!root) return 0;
        // Ignore negative paths if we want max path sum from children
        int left = max(0, dfs(root->left));
        int right = max(0, dfs(root->right));

        // Update global max path passing through current node as apex
        maxSum = max(maxSum, left + right + root->val);

        // Return max path sum extending to parent
        return root->val + max(left, right);
    }
public:
    int maxPathSum(TreeNode* root) {
        dfs(root);
        return maxSum;
    }
};

int main() {
    TreeNode* root = new TreeNode(-10);
    root->left = new TreeNode(9);
    root->right = new TreeNode(20);
    root->right->left = new TreeNode(15);
    root->right->right = new TreeNode(7);

    Solution sol;
    cout << "Max Path Sum: " << sol.maxPathSum(root) << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

bool isSafe(const vector<vector<int>>& b, int r, int c, int d) {
    // row & column
    for (int i = 0; i < 9; ++i) if (b[r][i] == d || b[i][c] == d) return false;
    // 3x3 box
    int br = (r/3)*3, bc = (c/3)*3;
    for (int i = 0; i < 3; ++i)
        for (int j = 0; j < 3; ++j)
            if (b[br+i][bc+j] == d) return false;
    return true;
}

bool solve(vector<vector<int>>& b) {
    for (int r = 0; r < 9; ++r) {
        for (int c = 0; c < 9; ++c) {
            if (b[r][c] == 0) {               // empty cell
                for (int d = 1; d <= 9; ++d) {
                    if (isSafe(b, r, c, d)) {
                        b[r][c] = d;          // place digit
                        if (solve(b)) return true; // recurse
                        b[r][c] = 0;          // backtrack
                    }
                }
                return false; // no digit fits -> backtrack
            }
        }
    }
    return true; // board filled
}

