#include <algorithm>
using namespace std;

const int INF = 1e9;
int n = 4;
vector<vector<int>> dist = {
    {0, 10, 15, 20},
    {10, 0, 35, 25},
    {15, 35, 0, 30},
    {20, 25, 30, 0}
};

int tsp(int mask, int pos, vector<vector<int>>& memo) {
    if (mask == (1 << n) - 1) return dist[pos][0]; // return to start
    if (memo[mask][pos] != -1) return memo[mask][pos];

    int ans = INF;
    for (int city = 0; city < n; city++) {
        if ((mask & (1 << city)) == 0) {
            ans = min(ans, dist[pos][city] + tsp(mask | (1 << city), city, memo));
        }
    }
    return memo[mask][pos] = ans;
}

int main() {
    vector<vector<int>> memo(1 << n, vector<int>(n, -1));
    cout << "Minimum TSP Cost: " << tsp(1, 0, memo) << endl;
    return 0;
}

#include <iostream>
