using namespace std;

long long memo[20][180][2];

long long countValid(int idx, int sum, bool tight, const vector<int>& digits) {
    if (idx == digits.size()) return sum;
    if (memo[idx][sum][tight] != -1) return memo[idx][sum][tight];

    long long total = 0;
    int limit = tight ? digits[idx] : 9;

    for (int d = 0; d <= limit; d++) {
        total += countValid(idx + 1, sum + d, tight && (d == limit), digits);
    }
    return memo[idx][sum][tight] = total;
}

long long solveForN(long long n) {
    if (n < 0) return 0;
    vector<int> digits;
    while (n > 0) {
        digits.push_back(n % 10);
        n /= 10;
    }
    reverse(digits.begin(), digits.end());
    memset(memo, -1, sizeof(memo));
    return countValid(0, 0, true, digits);
}

