#include <iostream>
#include <vector>
using namespace std;

void solveNQueens(int row, int n, vector<string>& board, vector<bool>& cols, vector<bool>& d1, vector<bool>& d2, int& count) {
    if (row == n) {
        count++;
        return;
    }
    for (int col = 0; col < n; col++) {
        if (!cols[col] && !d1[row - col + n - 1] && !d2[row + col]) {
            // Make choice
            board[row][col] = 'Q';
            cols[col] = d1[row - col + n - 1] = d2[row + col] = true;

            // Recurse
            solveNQueens(row + 1, n, board, cols, d1, d2, count);

            // Undo choice (Backtrack)
            board[row][col] = '.';
            cols[col] = d1[row - col + n - 1] = d2[row + col] = false;
        }
    }
}

int main() {
    int n = 4, count = 0;
    vector<string> board(n, string(n, '.'));
    vector<bool> cols(n, false), d1(2 * n, false), d2(2 * n, false);
    solveNQueens(0, n, board, cols, d1, d2, count);
    cout << "Total solutions for 4-Queens: " << count << endl;
    return 0;
}

#include <iostream>
