void solve(int i, vector<int>& nums, vector<int>& ds, vector<vector<int>>& ans) {
    if (i == nums.size()) {
        ans.push_back(ds); // Base case: store subset
        return;
    }
    ds.push_back(nums[i]); // Pick the element
    solve(i + 1, nums, ds, ans);
    ds.pop_back(); // Backtrack
    solve(i + 1, nums, ds, ans); // Do not pick the element
}

