void recurPermute(vector<int>& nums, vector<int>& ds, vector<vector<int>>& ans, vector<bool>& freq) {
    if (ds.size() == nums.size()) {
        ans.push_back(ds);
        return;
    }
    for (int i = 0; i < nums.size(); i++) {
        if (!freq[i]) {
            freq[i] = true;
            ds.push_back(nums[i]);
            recurPermute(nums, ds, ans, freq);
            ds.pop_back(); // Backtrack
            freq[i] = false;
        }
    }
}

