dsa.word-search.syntax:
bool dfs(int r, int c, int index, vector<vector<char>>& board, string& word) {
    if (index == word.size()) return true;
    if (r < 0 || c < 0 || r >= board.size() || c >= board[0].size() || board[r][c] != word[index]) return false;
    char temp = board[r][c];
    board[r][c] = '#';
    bool found = dfs(r+1, c, index+1, board, word) || dfs(r-1, c, index+1, board, word) ||
                 dfs(r, c+1, index+1, board, word) || dfs(r, c-1, index+1, board, word);
    board[r][c] = temp;
    return found;
}

