#include <iostream>
#include <vector>
#include <string>

using namespace std;

class Solution {
public:
    bool dfs(int r, int c, int idx, vector<vector<char>>& board, string& word) {
        if (idx == word.size()) return true;
        if (r < 0 || c < 0 || r >= board.size() || c >= board[0].size() || board[r][c] != word[idx]) return false;

        char temp = board[r][c];
        board[r][c] = '#'; // Mark as visited

        bool found = dfs(r + 1, c, idx + 1, board, word) ||
                     dfs(r - 1, c, idx + 1, board, word) ||
                     dfs(r, c + 1, idx + 1, board, word) ||
                     dfs(r, c - 1, idx + 1, board, word);

        board[r][c] = temp; // Backtrack
        return found;
    }

    bool exist(vector<vector<char>>& board, string word) {
        for (int i = 0; i < board.size(); ++i) {
            for (int j = 0; j < board[0].size(); ++j) {
                if (dfs(i, j, 0, board, word)) return true;
            }
        }
        return false;
    }
};

int main() {
    vector<vector<char>> board = {{'A','B','C','E'}, {'S','F','C','S'}, {'A','D','E','E'}};
    Solution sol;
    cout << (sol.exist(board, "ABCCED" ) ? "Found" : "Not Found") << endl;
    return 0;
}

