// Simple illustration of bounding for 0/1 Knapsack
struct Item {
    int weight, value;
};

float bound(int capacity, int n, int idx, int currentWeight, int currentVal, const vector<Item>& items) {
    float boundVal = currentVal;
    int totalWeight = currentWeight;

    for (int i = idx; i < n; ++i) {
        if (totalWeight + items[i].weight <= capacity) {
            totalWeight += items[i].weight;
            boundVal += items[i].value;
        } else {
            boundVal += (items[i].value * (float)(capacity - totalWeight) / items[i].weight);
            break;
        }
    }
    return boundVal;
}

