// Fast exponentiation (binary exponentiation) modulo mod
long long fastPower(long long a, long long n, long long mod) {
    long long result = 1 % mod;   // handle mod = 1
    a %= mod;                     // bring base within mod range
    while (n > 0) {
        if (n & 1)               // if current LSB is 1
            result = (result * a) % mod; // multiply into result
        a = (a * a) % mod;       // square the base
        n >>= 1;                 // shift exponent right
    }
    return result;
}

