#include <bits/stdc++.h>
using namespace std;

// Cyclic Sort to find the missing number in an array containing 1..n with one missing
int findMissing(vector<int>& arr) {
    int n = arr.size(); // actually n = expected size = arr.size()+1
    for (int i = 0; i < n; ++i) {
        // place arr[i] at its correct index arr[i]-1
        while (arr[i] >= 1 && arr[i] <= n && arr[i] != arr[arr[i]-1]) {
            swap(arr[i], arr[arr[i]-1]);
        }
    }
    // after placement, the index where value != index+1 is the missing number
    for (int i = 0; i < n; ++i) {
        if (arr[i] != i+1) return i+1; // missing
    }
    return n+1; // if none missing (should not happen here)
}

int main() {
    vector<int> a = {3, 1, 2, 5}; // numbers 1..5, 4 is missing
    cout << "Missing number: " << findMissing(a) << "\n"; // Expected: 4
    return 0;
}

