// C++ STL priority_queue
using MaxHeap = std::priority_queue<int>; // default max‑heap
using MinHeap = std::priority_queue<int, std::vector<int>, std::greater<int>>;

code.src:
#include <bits/stdc++.h>
using namespace std;

// Top‑K largest elements using a min‑heap
vector<int> topK(const vector<int>& arr, int k){
    MinHeap pq; // stores the current k largest
    for(int x:arr){
        pq.push(x);
        if(pq.size()>k) pq.pop(); // remove smallest among the k+1
    }
    vector<int> res; while(!pq.empty()){res.push_back(pq.top()); pq.pop();}
    sort(res.rbegin(), res.rend()); // descending order
    return res;
}

// K‑way merge of k sorted vectors
vector<int> kWayMerge(const vector<vector<int>>& lists){
    struct Node{int val; int i; int j;}; // value, list index, element index
    auto cmp = [](const Node& a, const Node& b){return a.val > b.val;}; // min‑heap
    priority_queue<Node, vector<Node>, decltype(cmp)> pq(cmp);
    for(int i=0;i<lists.size();++i) if(!lists[i].empty())
        pq.push({lists[i][0], i, 0});
    vector<int> out;
    while(!pq.empty()){
        Node cur = pq.top(); pq.pop();
        out.push_back(cur.val);
        if(cur.j+1 < lists[cur.i].size())
            pq.push({lists[cur.i][cur.j+1], cur.i, cur.j+1});
    }
    return out;
}

int main(){
    vector<int> a={5,1,9,3,14,7};
    auto res=topK(a,3); // expects {14,9,7}
    for(int x:res) cout<<x<<" "; cout<<"\n";
    vector<vector<int>> lists={{1,4,9},{2,5,8},{3,6,7}};
    auto merged=kWayMerge(lists); // expects 1..9
    for(int x:merged) cout<<x<<" "; cout<<"\n";
}

