#include <iostream>
#include <vector>
#include <queue>

using namespace std;

// BFS shortest path in unweighted graph
int shortestPath(int V, vector<vector<int>>& adj, int start, int target) {
    vector<int> dist(V, -1);
    queue<int> q;

    q.push(start);
    dist[start] = 0;

    while (!q.empty()) {
        int u = q.front();
        q.pop();

        if (u == target) return dist[u];

        for (int v : adj[u]) {
            if (dist[v] == -1) { // Unvisited
                dist[v] = dist[u] + 1;
                q.push(v);
            }
        }
    }
    return -1; // Unreachable
}

int main() {
    int V = 5;
    vector<vector<int>> adj(V);
    adj[0] = {1, 2};
    adj[1] = {0, 3};
    adj[2] = {0, 4};
    adj[3] = {1};
    adj[4] = {2};

    cout << "Shortest distance from 0 to 3: " << shortestPath(V, adj, 0, 3) << endl;
    return 0;
}

