#include <iostream>
#include <vector>
using namespace std;

// Function to generate Pascal's Triangle and compute nCr
vector<vector<long long>> generatePascal(int n) {
    vector<vector<long long>> dp(n + 1, vector<long long>(n + 1, 0));
    for (int i = 0; i <= n; i++) {
        dp[i][0] = 1; // Base case: nC0 = 1
        for (int j = 1; j <= i; j++) {
            // Pascal's identity
            dp[i][j] = dp[i - 1][j - 1] + dp[i - 1][j];
        }
    }
    return dp;
}

int main() {
    int n = 5, r = 2;
    vector<vector<long long>> pascal = generatePascal(n);
    cout << n << "C" << r << " = " << pascal[n][r] << endl;
    return 0;
}

