#include <iostream>
#include <vector>
#include <unordered_map>
using namespace std;

// Pattern: Sliding Window (Maximum Sum Subarray of size K)
int maxSumSubarray(int k, const vector<int>& arr) {
    int maxSum = 0, windowSum = 0;
    int windowStart = 0;
    for (int windowEnd = 0; windowEnd < arr.size(); windowEnd++) {
        windowSum += arr[windowEnd]; // Add next element
        // Slide the window if we reach size k
        if (windowEnd >= k - 1) {
            maxSum = max(maxSum, windowSum);
            windowSum -= arr[windowStart]; // Subtract element going out
            windowStart++; // Slide window ahead
        }
    }
    return maxSum;
}

int main() {
    vector<int> arr = {2, 1, 5, 1, 3, 2};
    int k = 3;
    cout << "Max Subarray Sum (k=3): " << maxSumSubarray(k, arr) << endl;
    return 0;
}

