// Safe implementation handling edge cases
int findMax(const std::vector<int>& nums) {
    if (nums.empty()) {
        return -1; // Edge case: empty input handled
    }
    int maxVal = nums[0];
    for (size_t i = 1; i < nums.size(); ++i) {
        if (nums[i] > maxVal) {
            maxVal = nums[i];
        }
    }
    return maxVal;
}

int main() {
